using System;
using System.Linq;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Opaque (IBettaValue), so it
    /// travels between components as a single "Panel" wire.
    /// </summary>
    public sealed class Panel : IBettaValue
    {
        private readonly Point3d[] _corners;
        private readonly double[] _edges;
        private readonly double[] _diagonals;

        /// <summary>Creates a panel from four corners given in order around the panel.</summary>
        public Panel(int index, Point3d[] corners)
        {
            if (corners == null || corners.Length != 4)
                throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            Index = index;
            _corners = (Point3d[])corners.Clone();

            _edges = new double[4];
            for (int i = 0; i < 4; i++)
                _edges[i] = _corners[i].DistanceTo(_corners[(i + 1) % 4]);

            _diagonals = new[] { _corners[0].DistanceTo(_corners[2]), _corners[1].DistanceTo(_corners[3]) };

            Width = (_edges[0] + _edges[2]) / 2.0;
            Height = (_edges[1] + _edges[3]) / 2.0;

            Point3d c0 = _corners[0], c1 = _corners[1], c2 = _corners[2], c3 = _corners[3];

            Area = 0.5 * (Vector3d.CrossProduct(c1 - c0, c2 - c0).Length
                        + Vector3d.CrossProduct(c2 - c0, c3 - c0).Length);

            Vector3d sum = (c0 - Point3d.Origin) + (c1 - Point3d.Origin)
                         + (c2 - Point3d.Origin) + (c3 - Point3d.Origin);
            Center = Point3d.Origin + sum / 4.0;

            // Distance from the fourth corner to the plane through the other three.
            Vector3d normal = Vector3d.CrossProduct(c1 - c0, c2 - c0);
            if (normal.Length < 1e-12)
            {
                // Degenerate first three corners: no plane, so report NaN (never "flat").
                Deviation = double.NaN;
            }
            else
            {
                normal.Unitize();
                Deviation = Math.Abs(normal * (c3 - c0));
            }
        }

        /// <summary>Position in the grid (row-major: U varies fastest).</summary>
        public int Index { get; }

        /// <summary>Planarity deviation: distance from corner 4 to the plane through corners 1-3.</summary>
        public double Deviation { get; }

        /// <summary>Area of the quad, split into two triangles.</summary>
        public double Area { get; }

        /// <summary>Average of the four corners.</summary>
        public Point3d Center { get; }

        /// <summary>Mean of the first and third edge lengths.</summary>
        public double Width { get; }

        /// <summary>Mean of the second and fourth edge lengths.</summary>
        public double Height { get; }

        /// <summary>A copy of the four corners, in order around the panel.</summary>
        public Point3d[] Corners => (Point3d[])_corners.Clone();

        /// <summary>Closed polyline through the four corners.</summary>
        public Curve Outline => new PolylineCurve(new[]
        {
            _corners[0], _corners[1], _corners[2], _corners[3], _corners[0]
        });

        /// <summary>Edge lengths sorted ascending.</summary>
        public double[] SortedEdges() => _edges.OrderBy(v => v).ToArray();

        /// <summary>Diagonal lengths sorted ascending.</summary>
        public double[] SortedDiagonals() => _diagonals.OrderBy(v => v).ToArray();
    }
}

