using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>Result of nesting: placed rectangles in placement order, plus summary numbers.</summary>
    public sealed class NestResult
    {
        public List<Curve> Outlines { get; } = new List<Curve>();
        public List<int> Sheets { get; } = new List<int>();
        public int SheetCount { get; set; }
        public double Utilization { get; set; }
        public int Unplaced { get; set; }
    }

    /// <summary>
    /// Shelf-packing of panel rectangles onto sheets. Parts are taken tallest first and placed
    /// left to right on a shelf. A part that doesn't fit starts a new shelf above, and a shelf
    /// that doesn't fit starts a new sheet. A part is turned 90 degrees only when it fits
    /// turned and not as-is. Spacing is the gap between parts and from the sheet edge.
    /// </summary>
    public static class ShelfNester
    {
        /// <summary>Gap between neighbouring sheets when laid out side by side along X.</summary>
        public const double SheetGap = 100.0;

        public static NestResult Pack(
            IReadOnlyList<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<int> progress,
            CancellationToken ct)
        {
            var result = new NestResult();
            if (panels.Count == 0) return result;

            double xMin = spacing, xMax = sheetWidth - spacing;
            double yMin = spacing, yMax = sheetHeight - spacing;

            // Tallest first; OrderBy is stable, so equal heights keep their grid order.
            var parts = panels
                .Select(p => (Width: p.Width, Height: p.Height))
                .OrderByDescending(p => p.Height)
                .ToList();

            var placed = new List<(int Sheet, double X, double Y, double W, double H)>();

            int sheet = 0;
            double shelfY = yMin, shelfHeight = 0, cursorX = xMin;
            bool shelfHasParts = false;
            double lastPercent = -1;

            bool TryOnShelf(double w, double h)
            {
                // As-is first.
                if (cursorX + w <= xMax && shelfY + h <= yMax)
                {
                    Place(w, h);
                    return true;
                }
                // Turned, only when it fits turned.
                if (cursorX + h <= xMax && shelfY + w <= yMax)
                {
                    Place(h, w);
                    return true;
                }
                return false;
            }

            void Place(double pw, double ph)
            {
                placed.Add((sheet, cursorX, shelfY, pw, ph));
                cursorX += pw + spacing;
                shelfHeight = Math.Max(shelfHeight, ph);
                shelfHasParts = true;
            }

            for (int i = 0; i < parts.Count; i++)
            {
                ct.ThrowIfCancellationRequested();
                var (w, h) = parts[i];

                if (!FitsEmptySheet(w, h, xMax - xMin, yMax - yMin))
                {
                    result.Unplaced++;
                }
                else if (!TryOnShelf(w, h))
                {
                    // New shelf above, only if the current shelf has parts on it.
                    bool placedOnNewShelf = false;
                    if (shelfHasParts)
                    {
                        shelfY += shelfHeight + spacing;
                        cursorX = xMin;
                        shelfHeight = 0;
                        shelfHasParts = false;
                        placedOnNewShelf = TryOnShelf(w, h);
                    }

                    if (!placedOnNewShelf)
                    {
                        // New sheet.
                        sheet++;
                        shelfY = yMin;
                        cursorX = xMin;
                        shelfHeight = 0;
                        shelfHasParts = false;
                        if (!TryOnShelf(w, h)) result.Unplaced++;
                    }
                }

                int percent = (int)((i + 1) * 100L / parts.Count);
                if (progress != null && percent != lastPercent)
                {
                    lastPercent = percent;
                    progress.Report(percent);
                }
            }

            int sheetCount = placed.Count == 0 ? 0 : placed.Max(p => p.Sheet) + 1;
            double usedArea = 0;

            foreach (var r in placed)
            {
                double offsetX = r.Sheet * (sheetWidth + SheetGap);
                double x0 = r.X + offsetX, y0 = r.Y, x1 = x0 + r.W, y1 = y0 + r.H;
                result.Outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(x0, y0, 0), new Point3d(x1, y0, 0),
                    new Point3d(x1, y1, 0), new Point3d(x0, y1, 0), new Point3d(x0, y0, 0)
                }));
                result.Sheets.Add(r.Sheet);
                usedArea += r.W * r.H;
            }

            result.SheetCount = sheetCount;
            result.Utilization = sheetCount == 0 ? 0 : usedArea / (sheetCount * sheetWidth * sheetHeight);
            return result;
        }

        private static bool FitsEmptySheet(double w, double h, double usableW, double usableH)
            => (w <= usableW && h <= usableH) || (h <= usableW && w <= usableH);
    }
}

