    public sealed class PanelGroups
    {
        public List<int> Group { get; } = new List<int>();
        public int GroupCount { get; set; }
        public List<Panel> Representatives { get; } = new List<Panel>();
    }

    /// <summary>
    /// Groups panels that are identical within a tolerance. Two panels are identical when their
    /// sorted edge lengths and their sorted diagonal lengths each differ by at most the tolerance.
    /// Each panel is compared with the first panel of every existing group.
    /// </summary>
    public static class PanelGrouping
    {
        public static PanelGroups Group(IReadOnlyList<Panel> panels, double tolerance)
        {
            var result = new PanelGroups();

            foreach (var panel in panels)
            {
                int found = -1;
                for (int g = 0; g < result.Representatives.Count && found < 0; g++)
                {
                    if (AreIdentical(panel, result.Representatives[g], tolerance)) found = g;
                }

                if (found < 0)
                {
                    found = result.Representatives.Count;
                    result.Representatives.Add(panel);
                }
                result.Group.Add(found);
            }

            result.GroupCount = result.Representatives.Count;
            return result;
        }

        private static bool AreIdentical(Panel a, Panel b, double tolerance)
            => WithinTolerance(a.SortedEdges(), b.SortedEdges(), tolerance)
            && WithinTolerance(a.SortedDiagonals(), b.SortedDiagonals(), tolerance);

        private static bool WithinTolerance(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
            {
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            }
            return true;
        }
    }
}

