namespace BenchPlugin.Facade
{
    public class PanelsPack : IPanelsPack
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Brep surface, int uCount, int vCount)
        {
            if (uCount < 1 || vCount < 1)
                throw new ArgumentException($"U Count and V Count must be at least 1 (got {uCount} and {vCount}).");
            if (surface == null || surface.Faces.Count != 1)
                throw new ArgumentException("Surface must be a single face (a Brep with exactly one face).");

            BrepFace face = surface.Faces[0];
            Interval du = face.Domain(0);
            Interval dv = face.Domain(1);

            var us = new double[uCount + 1];
            for (int i = 0; i <= uCount; i++) us[i] = du.ParameterAt(i / (double)uCount);
            var vs = new double[vCount + 1];
            for (int j = 0; j <= vCount; j++) vs[j] = dv.ParameterAt(j / (double)vCount);

            var panels = new List<Panel>(uCount * vCount);
            var outlines = new List<Curve>(uCount * vCount);

            for (int j = 0; j < vCount; j++)
            {
                for (int i = 0; i < uCount; i++)
                {
                    // Corners in order around the panel: (u0,v0), (u1,v0), (u1,v1), (u0,v1).
                    var corners = new[]
                    {
                        face.PointAt(us[i],     vs[j]),
                        face.PointAt(us[i + 1], vs[j]),
                        face.PointAt(us[i + 1], vs[j + 1]),
                        face.PointAt(us[i],     vs[j + 1]),
                    };

                    var panel = new Panel(j * uCount + i, corners);
                    panels.Add(panel);
                    outlines.Add(panel.Outline);
                }
            }

            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentException("Panel is missing.");
            return (new List<Point3d>(panel.Corners), panel.Outline, panel.Area, panel.Center, panel.Index);
        }
    }
}

