using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class FabricationPack : IFabricationPack
    {
        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            PanelGroups groups = PanelGrouping.Group(panels ?? new List<Panel>(), tolerance);
            return (groups.Group, groups.GroupCount, groups.Representatives);
        }

        public async Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IBettaReport report,
            IProgress<int> progress,
            CancellationToken ct)
        {
            if (sheetWidth <= 0 || sheetHeight <= 0)
                throw new ArgumentException($"Sheet Width and Sheet Height must be positive (got {sheetWidth} x {sheetHeight}).");
            if (spacing < 0)
                throw new ArgumentException($"Spacing cannot be negative (got {spacing}).");
            if (2 * spacing >= sheetWidth || 2 * spacing >= sheetHeight)
                throw new ArgumentException("Spacing leaves no room on the sheet.");

            panels = panels ?? new List<Panel>();

            // Packing is CPU-bound; keep it off the UI thread. Betta cancels ct when inputs change.
            NestResult result = await Task.Run(
                () => ShelfNester.Pack(panels, sheetWidth, sheetHeight, spacing, progress, ct), ct);

            if (result.Unplaced > 0)
            {
                report.Warning($"{result.Unplaced} of {panels.Count} panels fit on no sheet.");
            }

            return (result.Outlines, result.Sheets, result.SheetCount, result.Utilization);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Write is true but Path is empty. Set a file path to write the CSV.");

            panels = panels ?? new List<Panel>();
            var inv = CultureInfo.InvariantCulture;

            var sb = new StringBuilder();
            sb.AppendLine("index,width,height,area,deviation");
            foreach (var p in panels)
            {
                sb.AppendLine(string.Join(",",
                    p.Index.ToString(inv),
                    p.Width.ToString("F3", inv),
                    p.Height.ToString("F3", inv),
                    p.Area.ToString("F3", inv),
                    p.Deviation.ToString("F3", inv)));
            }

            string csv = sb.ToString();
            bool written = false;
            if (write)
            {
                File.WriteAllText(path, csv);
                written = true;
            }

            return (csv, written);
        }
    }
}

